import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../../../l10n/l10n.dart';
import '../../../models/isar/models/contact_entry.dart';
import '../../../notifications/show_flush_bar.dart';
import '../../../themes/coin_icon_provider.dart';
import '../../../themes/stack_colors.dart';
import '../../../utilities/assets.dart';
import '../../../utilities/clipboard_interface.dart';
import '../../../utilities/text_styles.dart';
import '../../../widgets/custom_buttons/blue_text_button.dart';
import '../../../utilities/contact_address_title.dart';
import '../../../widgets/middle_ellipsis_text.dart';

class DesktopAddressCard extends ConsumerWidget {
  const DesktopAddressCard({
    super.key,
    required this.entry,
    this.clipboard = const ClipboardWrapper(),
  });

  final ContactAddressEntry entry;
  final ClipboardInterface clipboard;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SvgPicture.file(
          File(ref.watch(coinIconProvider(entry.coin))),
          height: 32,
          width: 32,
        ),
        const SizedBox(width: 16),
        Flexible(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SelectableText(
                entry.title,
                style: STextStyles.desktopTextExtraExtraSmall(context).copyWith(
                  color: Theme.of(context).extension<StackColors>()!.textDark,
                ),
              ),
              const SizedBox(height: 2),
              MiddleEllipsisText(
                entry.address,
                style: STextStyles.desktopTextExtraExtraSmall(context),
              ),
              const SizedBox(height: 8),
              CustomTextButton(
                text: l10n.commonCopy,
                onTap: () {
                  clipboard.setData(ClipboardData(text: entry.address));
                  showFloatingFlushBar(
                    type: FlushBarType.info,
                    message: l10n.commonCopiedToClipboard,
                    iconAsset: Assets.svg.copy,
                    context: context,
                  );
                },
              ),
            ],
          ),
        ),
      ],
    );
  }
}
